// Entrada: POST /simulador/dse  body {ligado:true|false}   (chamado pelo botao "Ligar/Desligar gerador (Demo)" do HTML)
// Saida 1 -> s7 out (escritas no PLC)   Saida 2 -> HTTP response
const b = msg.payload || {};
if (typeof b.ligado !== 'boolean') {
  msg.statusCode = 400;
  msg.payload = { ok: false, erro: 'ligado deve ser true/false' };
  return [null, msg];
}
flow.set('simLigado', b.ligado);
let w;
if (b.ligado) {
  w = [
    { variable: 'ledManual',  payload: true },   // DB52 ledManual = gerador em START/operando
    { variable: 'tensaoL1L2', payload: 221.1 },  // mesmos valores padrao do Demo do HTML
    { variable: 'tensaoL2L3', payload: 220.8 },
    { variable: 'tensaoL3L1', payload: 221.3 }
  ];
} else {
  w = [
    { variable: 'ledManual',  payload: false },
    { variable: 'tensaoL1L2', payload: 0 },
    { variable: 'tensaoL2L3', payload: 0 },
    { variable: 'tensaoL3L1', payload: 0 },
    { variable: 'potenciaKw', payload: 0 }
  ];
  for (let i = 1; i <= 16; i++) w.push({ variable: 'Ligada' + i, payload: false }); // limpa o feedback simulado
}
msg.statusCode = 200;
msg.payload = { ok: true, ligado: b.ligado };
return [w, msg];

// Entrada: leitura ciclica (s7 in "all", 200 ms). So age com o gerador SIMULADO ligado (flow 'simLigado').
// 1) Ligada1..16 (sb.ligada) = cbLigar (comando) -> simula a realimentacao fisica; escreve so quando muda
// 2) potenciaKw = kW sem carga + soma dos kW nominais das chaves com cb.ligar = true; escrita no maximo 1x por segundo
if (!flow.get('simLigado')) return null;
const p = msg.payload;
if (!p || typeof p !== 'object') return null;
const KW = [5, 5, 5, 5, 5, 4, 4, 4, 4, 4, 4, 4, 3, 0, 0, 0];   // kW nominais BC56 (ESPECIFICACAO_CARD_CHAVES_DB55_FB200.md, secao 2); 14-16 sem chave
const BASE = 0.8;                                             // kW sem carga SIMULADO (valor de simulacao, ajuste se quiser)
const out = [];
let carga = 0;
for (let i = 1; i <= 16; i++) {
  const cmd = (p['CbLigar' + i] === true);
  if (cmd) carga += KW[i - 1];
  if (p['Ligada' + i] !== cmd) out.push({ variable: 'Ligada' + i, payload: cmd });
}
const agora = Date.now();
if (agora - (flow.get('simUltPot') || 0) >= 1000) {
  flow.set('simUltPot', agora);
  out.push({ variable: 'potenciaKw', payload: Math.round((BASE + carga + (Math.random() - 0.5) * 0.1) * 100) / 100 });
}
return out.length ? [out] : null;
